+
+func (s *Syncer) tick(ctx context.Context) {
+	stores, err := s.Store.ListVaultCredentialStores(ctx)
+	if err != nil {
+		s.Logger.Warn("listing credential stores failed", slog.String("err", err.Error()))
+		return
