+	now := s.Clock()
+	for _, cs := range stores {
+		if cs.Kind != KindInfisical {
+			continue
+		}
+		if !s.dueAt(cs, now) {
+			continue
+		}
+		if !s.markInFlight(cs.VaultID) {
+			continue // a previous refresh for this vault is still running
+		}
