+	if err := s.Store.UpdateVaultCredentialStoreHealth(ctx, cs.VaultID, StatusOK, "", s.Clock()); err != nil {
+		s.Logger.Warn("updating health=ok failed",
+			slog.String("vault_id", cs.VaultID),
+			slog.String("err", err.Error()))
+	}
